CREATE TABLE IF NOT EXISTS employees (id BIGINT AUTO_INCREMENT PRIMARY KEY, employee_code VARCHAR(20) NOT NULL UNIQUE, full_name VARCHAR(120) NOT NULL, email VARCHAR(320) NOT NULL, phone VARCHAR(20) NOT NULL, department VARCHAR(80) NOT NULL, designation VARCHAR(120) NOT NULL, basic_salary DECIMAL(12,2) NOT NULL, joining_date DATE NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);